      <rect class="bar" x="136" y="70.5" width="28" height="4.5"  rx="2"></rect>
      <rect class="bar" x="176" y="18"   width="28" height="57"   rx="2"></rect>
      <rect class="bar" x="216" y="51"   width="28" height="24"   rx="2"></rect>
      <rect class="bar" x="256" y="64.5" width="28" height="10.5" rx="2"></rect>
      <text class="lbl" x="16"  y="86">Fri</text>
